'use strict';
// Модуль «Проекты контрагентов»
/* ═════════════ Проекты контрагентов ═════════════ */
const projVisible=p=>seeAll('projects')||p.resps.includes(S.me)||(CPM[p.cp]&&CPM[p.cp].resp===S.me);
const projActive=p=>p.status==='В работе'||p.status==='Планируется';
const workOver=w=>!w.done&&w.due&&w.due<TODAY;
function projTabs(){const v=PROJECTS.filter(projVisible);return [{id:'active',label:'Активные',icon:'briefcase',count:v.filter(projActive).length},{id:'all',label:'Все',icon:'list'},{id:'mine',label:'Мои',icon:'user',count:v.filter(p=>p.resps.includes(S.me)&&projActive(p)).length}]}
function projAdd(){return can('projects')?[{label:'Проект',icon:'briefcase',run:()=>projectDlg()}]:[]}
function projCols(){const mv=moneyVis();return [
 {key:'name',label:'Проект',type:'text',w:280,val:p=>p.name,html:p=>`<span class="strong">${esc(p.name)}</span>`},
 {key:'cp',label:'Контрагент',type:'enum',w:210,val:p=>CPM[p.cp].name},
 {key:'status',label:'Статус',type:'enum',w:170,val:p=>p.status,html:p=>scaleMini('proj',p.status,p)+(projOver(p)?` <span class="pill red sm">${ic('alert')}срок прошёл</span>`:'')},
 {key:'from',label:'Начало',type:'date',w:110,val:p=>p.from},{key:'to',label:'Окончание',type:'date',w:120,val:p=>p.to,html:p=>`<span class="${projOver(p)?'red strong':''}">${fmtD(p.to)}</span>`},
 {key:'lead',label:'Главный',type:'enum',w:130,val:p=>empName(p.lead),hide:true},
 {key:'resps',label:'Ответственные',type:'text',w:190,val:p=>p.resps.map(empName).join(', ')},
 {key:'desc',label:'Описание',type:'text',w:240,val:p=>p.desc||'',hide:true},
 {key:'works',label:'Работы',type:'num',w:130,num:true,hide:true,val:p=>p.works.length?p.works.filter(w=>w.done).length/p.works.length:0,html:p=>p.works.length?`${p.works.filter(w=>w.done).length} из ${p.works.length}${p.works.some(workOver)?` <span class="red" title="Есть работы с прошедшим сроком">${ic('alert','sm')}</span>`:''}`:'<span class="faint">—</span>'},
 {key:'nworks',label:'Работ всего',type:'int',w:110,num:true,val:p=>p.works.length,hide:true},
 {key:'pfiles',label:'Файлов',type:'int',w:90,num:true,val:p=>p.files.length,hide:true},
 {key:'tasks',label:'Задач открыто',type:'int',w:120,num:true,val:p=>TASKS.filter(t=>t.proj===p.id&&taskOpen(t)).length,hide:true},
 ...(mv?[{key:'plan',label:'Планируемая стоимость',type:'money',w:170,num:true,total:true,hide:true,val:p=>p.plan||null,html:p=>p.plan?fmtM(p.plan):'<span class="faint">не задана</span>'},{key:'paid',label:'Получено / план',type:'money',w:170,num:true,total:true,val:projPaid,html:p=>`${fmtM(projPaid(p))}${p.plan?` <span class="faint">/ ${fmtM(p.plan,false)}</span>`:''}`},
   {key:'left',label:'Остаток',type:'money',w:130,num:true,total:true,hide:true,val:p=>p.plan?projLeft(p):null,html:p=>!p.plan?'<span class="faint">—</span>':projLeft(p)>0?`<span class="strong">${fmtM(projLeft(p))}</span>`:'<span class="faint">0,00</span>'}]:[])]}
function setProjStatus(p,s){const o=p.status;p.status=s;log('p',p.id,`Статус: ${o} → ${s}`,p.cp);refreshAll();toast('Статус проекта: '+s)}
function projActions(p){const ed=can('projects');const it=[{label:'Открыть',icon:'briefcase',run:()=>openProject(p)}];
  if(ed)it.push({label:'Изменить',icon:'edit',run:()=>projectDlg(p)});
  if(ed&&moneyVis()&&p.status!=='Отменён')it.push({label:'Записать оплату',icon:'wallet',disabled:!!p.plan&&projLeft(p)<=0,reason:'Получена вся планируемая стоимость',run:()=>projPay(p)});
  if(feat('tasks')&&can('tasksCreate')&&p.status!=='Отменён')it.push({label:'Задача по проекту',icon:'task',run:()=>taskDlg(null,{cp:p.cp,proj:p.id,exec:p.lead})});
  if(ed){it.push({sep:true});scNext('proj',p.status).forEach(s=>it.push({label:s==='Завершён'?'Завершить':'В работу',icon:PRS[s][1],run:()=>setProjStatus(p,s)}));if(['Планируется','В работе'].includes(p.status))it.push({label:'Отменить проект',icon:PRS['Отменён'][1],danger:true,run:()=>confirmDlg({title:'Отменить проект?',text:`Проект «${esc(p.name)}» станет «Отменён». Вернуть его можно откатом (право «Откат статусов»).`,ok:'Отменить проект',danger:true,run:()=>setProjStatus(p,'Отменён')})});
    const bk=scBack('proj',p.status);if(bk)it.push({label:`Откатить в «${bk}»`,icon:'history',disabled:!can('rollback'),reason:'Нужно право «Откат статусов»',run:()=>rollbackDlg('proj',p.id,bk)})}
  it.push({label:'Карточка контрагента',icon:'building',run:()=>openCp(CPM[p.cp],'projects')});return it}
function renderProjects(body,tab,fresh){
  const v=PROJECTS.filter(projVisible);const run=v.filter(p=>p.status==='В работе'),plan=v.filter(p=>p.status==='Планируется'),over=v.filter(projOver);const left=v.filter(projActive).reduce((a,p)=>a+projLeft(p),0);
  body.innerHTML=`<div class="plates">${plate({id:'run',icon:'hourglass',color:'yellow',label:'В работе',value:run.length})}${plate({id:'plan',icon:'clock',color:'blue',label:'Планируются',value:plan.length})}${plate({id:'over',icon:'alert',color:over.length?'red':'green',label:'Срок прошёл',value:over.length,sub:over.length?'проект ещё в работе':'все в срок'})}${moneyVis()?plate({id:'left',icon:'wallet',color:'purple',label:'Осталось получить',value:fmtM(left,false),unit:'сом',sub:'по активным проектам с планом'}):''}</div><div id="pjg"></div>`;
  body.querySelector('.plates').onclick=e=>{const b=e.target.closest('[data-plate]');if(!b)return;const g=GS['proj-'+tab];if(!g)return;const k=b.dataset.plate;g.filters={};if(k==='run')g.filters.status={type:'enum',vals:['В работе']};if(k==='plan')g.filters.status={type:'enum',vals:['Планируется']};if(k==='over'){g.filters.status={type:'enum',vals:['В работе']};g.filters.to={type:'date',from:null,to:addDays(TODAY,-1)}}if(k==='left')g.filters.left={type:'num',from:1,to:null};g.page=0;renderPage()};
  const rows=()=>{const l=PROJECTS.filter(projVisible);if(tab==='active')return l.filter(projActive);if(tab==='mine')return l.filter(p=>p.resps.includes(S.me));return l};
  grid($('#pjg',body),{id:'proj-'+tab,cols:projCols(),rows,title:'name',noun:['проект','проекта','проектов'],sort:{key:'to',dir:1},rowClass:p=>projOver(p)?'overdue':p.status==='Отменён'||p.status==='Завершён'?'muted':'',preset:S.preset,simulateLoad:fresh,open:openProject,actions:projActions,
    empty:{icon:'briefcase',title:tab==='mine'?'Вы не ответственный ни в одном проекте':'Проектов пока нет',text:'Проект — разовая работа для контрагента за отдельную плату: восстановление учёта, постановка учёта, подготовка к проверке.',add:can('projects')&&tab!=='mine'?()=>projectDlg():null}});
}
function projPay(p){tranchDlg({title:'Оплата по проекту',sub:`${esc(p.name)} · ${esc(CPM[p.cp].name)}`,left:p.plan?projLeft(p):null,note:true,run:x=>{x.id=p.pays.length+1;x._ca=nowStamp();p.pays.push(x);log('p',p.id,`Оплата ${som(x.amount)}${x.note?' ('+x.note+')':''}`,p.cp,{sub:x.id})}})}
function openProject(p){if(!p)return;
  openModal({size:'wide',live:true,render:m=>{const c=CPM[p.cp];const ed=can('projects');const mine=ed||p.resps.includes(S.me);const done=p.works.filter(w=>w.done).length;const ts=TASKS.filter(t=>t.proj===p.id).sort((a,b)=>a.date<b.date?-1:1);const mv=moneyVis();const paid=projPaid(p);const pays=p.pays.filter(x=>!x.del);
    return {title:esc(p.name),sub:`${esc(c.name)} · ${fmtD(p.from)} – ${fmtD(p.to)}`,body:`<div class="box"><div class="scales">${scaleFull('proj',p.status,p.id)}${projOver(p)?`<span class="pill red" style="align-self:center">${ic('alert')}срок окончания прошёл</span>`:''}</div></div>
    ${statusHistHtml('proj',p)?`<div class="box"><h3>История статусов</h3>${statusHistHtml('proj',p)}</div>`:''}<div class="cols2"><div class="box"><div class="kv"><div><span class="k">Контрагент</span><span class="v"><button class="linkbtn" id="pj-cp">${esc(c.name)}</button></span></div><div><span class="k">Срок</span><span class="v">${fmtD(p.from)} – ${fmtD(p.to)}</span></div><div><span class="k">Главный ответственный</span><span class="v">${esc(empName(p.lead))}</span></div><div><span class="k">Ответственные</span><span class="v">${p.resps.map(e=>esc(empName(e))+(e===p.lead?' <span class="tag">главный</span>':'')).join(', ')}</span></div>${auditKv(p)}</div>${p.desc?`<p style="margin:0">${esc(p.desc)}</p>`:''}</div>
    ${mv?`<div class="box"><h3>Деньги по проекту</h3><div class="kv"><div><span class="k">Запланировано</span><span class="v tnum strong">${p.plan?som(p.plan):'<span class="faint">стоимость не задана</span>'}</span></div><div><span class="k">Получено</span><span class="v tnum">${som(paid)}</span></div><div><span class="k">Остаток</span><span class="v tnum ${p.plan&&projLeft(p)>0?'strong':''}">${p.plan?som(projLeft(p)):'—'}</span></div></div>${p.plan?`<div class="bar" role="progressbar" aria-valuenow="${paid}" aria-valuemax="${p.plan}"><i style="width:${Math.min(100,Math.round(paid/p.plan*100))}%"></i></div>`:''}</div>`:''}</div>
    <div class="box"><h3>Работы · ${done} из ${p.works.length}</h3>${p.works.length?`<div class="bar" role="progressbar" aria-valuenow="${done}" aria-valuemax="${p.works.length}"><i style="width:${Math.round(done/p.works.length*100)}%"></i></div>`:''}
      ${p.works.length?`<div class="tbl-wrap"><table class="mini"><thead><tr><th style="width:36px">Сделано</th><th>Работа</th><th>Исполнитель</th><th>Срок</th></tr></thead><tbody>${p.works.map((w,i)=>`<tr><td><input type="checkbox" data-w="${i}" ${w.done?'checked':''} ${mine?'':'disabled'} aria-label="Сделано: ${esc(w.n)}"></td><td style="${w.done?'text-decoration:line-through;color:var(--muted)':''}">${esc(w.n)}</td><td>${esc(empName(w.exec))}</td><td class="${workOver(w)?'red strong':''}">${w.due?fmtD(w.due):'<span class="faint">—</span>'}</td></tr>`).join('')}</tbody></table></div>`:'<span class="faint">Работы не заданы</span>'}
      ${mine?`<div class="row" style="flex-wrap:nowrap"><input class="inp" id="pj-w" placeholder="Добавить работу">${sel('pj-we',p.resps.map(e=>[e,empName(e)]),S.me&&p.resps.includes(S.me)?S.me:p.lead,'style="width:auto"')}<input class="inp" type="date" id="pj-wd" style="width:auto" aria-label="Срок работы"><button class="btn sm" id="pj-wa">${ic('plus','sm')}</button></div>`:''}</div>
    ${mv?`<div class="box"><h3>Оплаты (транши) · ${pays.length}<span class="grow"></span>${ed&&p.status!=='Отменён'&&!(p.plan&&projLeft(p)<=0)?`<button class="btn sm cta" id="pj-pay">${ic('wallet','sm')}Записать оплату</button>`:''}</h3>${pays.length?`<div class="tbl-wrap"><table class="mini m-cards"><thead><tr><th>Дата</th><th>Комментарий</th><th>Записал</th><th>Файлы</th><th class="num">Сумма</th><th style="width:36px"></th></tr></thead><tbody>${pays.map(x=>{const d={src:'pt',ref:x,own:p};return `<tr class="clk" data-opw="${esc(opKey(d))}" title="Открыть транш"><td>${fmtD(x.date)}${x.edited?' <span class="tag yellow">изменён</span>':''}</td><td>${esc(x.note||'')}</td><td>${esc(whoName(x.by))}</td><td>${(x.files||[]).map(esc).join(', ')||'<span class="faint">—</span>'}</td><td class="num">${fmtM(x.amount)}</td><td>${opMenuBtn(d)}</td></tr>`}).join('')}<tr class="m-total"><td colspan="4"><b>Получено</b></td><td class="num"><b>${fmtM(paid)}</b></td><td></td></tr></tbody></table></div>`:'<span class="faint">Оплат пока не было</span>'}<span class="hint">Каждая оплата попадает в «Финансовые операции по контрагентам». Транш можно открыть, изменить или удалить с причиной — в меню «…» строки.</span></div>`:''}
    ${feat('tasks')?`<div class="box"><h3>Задачи · ${ts.length}<span class="grow"></span>${can('tasksCreate')&&p.status!=='Отменён'?`<button class="btn sm" id="pj-task">${ic('plus','sm')}Задача</button>`:''}</h3>${ts.length?`<table class="mini"><tbody>${ts.map(t=>`<tr class="clk" data-task="${t.id}"><td>${esc(t.title)}</td><td>${esc(empName(t.exec))}</td><td class="${taskOver(t)?'red strong':''}">${fmtD(t.date)}</td><td>${pill(t.status,TST)}</td></tr>`).join('')}</tbody></table>`:'<span class="faint">Задач по проекту нет</span>'}</div>`:''}
    ${filesBox(p.files,'pj-f',mine,'Файлы',{ent:'p',id:p.id,cp:p.cp})}${histBox('p',p.id)}`,
    foot:`<button class="btn" id="pj-more">${ic('more','sm')}Действия</button><div class="grow"></div><button class="btn cta" data-close>Готово</button>`,
    mount(el,mm){const q=s=>el.querySelector(s);q('#pj-more').onclick=e=>menu(e.currentTarget,projActions(p).filter(x=>x.label!=='Открыть'));q('#pj-cp').onclick=()=>openCp(c,'projects');
      $$('[data-w]',el).forEach(x=>x.onchange=()=>{const w=p.works[+x.dataset.w];w.done=x.checked;log('p',p.id,`${w.done?'Сделано':'Снова в работе'}: ${w.n}`,p.cp);refreshAll()});
      const add=()=>{const v=val(el,'pj-w');if(!v)return;const w={n:v,done:false,exec:val(el,'pj-we')||S.me,due:val(el,'pj-wd')||null};p.works.push(w);log('p',p.id,`Добавлена работа: ${v} (${empName(w.exec)}${w.due?', до '+fmtD(w.due):''})`,p.cp);refreshAll()};if(q('#pj-wa')){q('#pj-wa').onclick=add;q('#pj-w').onkeydown=e=>{if(e.key==='Enter')add()}}
      if(q('#pj-pay'))q('#pj-pay').onclick=()=>projPay(p);
      if(q('#pj-task'))q('#pj-task').onclick=()=>taskDlg(null,{cp:p.cp,proj:p.id,exec:p.lead});
      $$('[data-task]',el).forEach(x=>x.onclick=()=>openTask(TASKS.find(t=>t.id===x.dataset.task)));
      bindFiles(el,'pj-f',p.files,f=>{log('p',p.id,'Прикреплены файлы: '+f.join(', '),p.cp);mm.draw()})}}}});
}
function projectDlg(p0,c0){const e=p0?{name:p0.name,cp:p0.cp,from:p0.from,to:p0.to,status:p0.status,resps:[...p0.resps],lead:p0.lead,desc:p0.desc,plan:p0.plan??'',works:p0.works.map(w=>Object.assign({},w))}
    :{name:'',cp:c0?c0.id:'',from:TODAY,to:addDays(TODAY,60),status:'Планируется',resps:c0&&c0.resp?[c0.resp]:[S.me],lead:c0&&c0.resp||S.me,desc:'',plan:'',works:[]};
  const mv=moneyVis();const rs='style="min-height:30px;padding:3px 8px"';
  openModal({form:true,size:'mid',render:m=>({title:p0?'Изменить проект':'Новый проект',sub:p0||c0?esc(CPM[e.cp].name):'Разовая работа за отдельную плату',body:`<div class="form">
    ${fld('Название проекта',inp('pd-name',e.name,'placeholder="Например: восстановление учёта 2024–2025"'),{req:true,full:true,id:'pd-name'})}
    ${p0||c0?'':fld('Контрагент',sel('pd-cp',[['','— выберите —'],...visCps(false,'projects').map(c=>[c.id,c.name])],e.cp),{req:true,full:true,id:'pd-cp',hint:'У контрагента может быть несколько проектов одновременно'})}
    ${fld('Срок с',inp('pd-from',e.from,'type="date"'),{req:true,id:'pd-from'})}${fld('Срок по',inp('pd-to',e.to,'type="date"'),{req:true,id:'pd-to'})}
    ${p0?fld('Статус',`<div class="v" style="padding-top:6px">${pill(e.status,PRS)}</div>`,{id:'pd-stv',hint:'Меняется на шкале статусов в карточке проекта'}):fld('Статус',sel('pd-st',['Планируется','В работе'],e.status),{id:'pd-st'})}${mv?fld('Планируемая стоимость, сом',inp('pd-plan',e.plan,'inputmode="decimal" class="inp tnum" placeholder="не обязательно"'),{id:'pd-plan',hint:p0&&projPaid(p0)?`Уже получено ${som(projPaid(p0))}`:'Можно не указывать, если стоимость договорная'}):'<div></div>'}
    ${fld('Ответственные',`<div class="chipsel" id="pd-resp">${EMP.filter(x=>x.active).map(x=>`<button type="button" data-e="${x.id}" class="${e.resps.includes(x.id)?'on':''}">${e.resps.includes(x.id)?ic('check','sm'):''}${esc(x.short)}</button>`).join('')}</div>`,{req:true,full:true,id:'pd-resp',hint:'Можно выбрать нескольких'})}
    ${fld('Главный ответственный',sel('pd-lead',e.resps.map(x=>[x,empName(x)]),e.lead),{id:'pd-lead'})}<div></div>
    ${fld('Описание',`<textarea class="inp" id="pd-desc" style="min-height:56px">${esc(e.desc)}</textarea>`,{full:true,id:'pd-desc'})}
    ${fld('Работы',`${e.works.length?`<table class="mini"><thead><tr><th>Работа</th><th>Исполнитель</th><th>Срок</th><th></th></tr></thead><tbody>${e.works.map((w,i)=>`<tr><td><input class="inp" data-wn="${i}" value="${esc(w.n)}" ${rs} aria-label="Работа"></td><td>${sel('pd-we'+i,EMP.filter(x=>x.active).map(x=>[x.id,x.short]),w.exec,`data-we="${i}" ${rs}`)}</td><td><input class="inp" type="date" data-wd="${i}" value="${w.due||''}" ${rs} aria-label="Срок"></td><td class="num">${w.done?'<span class="tag green">сделано</span>':`<button type="button" class="icon-btn sm" data-wrm="${i}" aria-label="Удалить работу">${ic('trash','sm')}</button>`}</td></tr>`).join('')}</tbody></table>`:'<span class="faint">Работ пока нет</span>'}<div class="row"><button type="button" class="btn sm" id="pd-wadd">${ic('plus','sm')}Работа</button></div>`,{full:true,id:'pd-works',hint:'Например: «подготовить документы к освоению». Отмечаются сделанными в карточке проекта'})}
    </div>`,
    foot:`<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="pd-ok">${p0?'Сохранить':'Создать проект'}</button>`,
    mount(el){const snap=()=>{e.name=val(el,'pd-name');if($('#pd-cp',el))e.cp=+val(el,'pd-cp')||'';e.from=val(el,'pd-from');e.to=val(el,'pd-to');if($('#pd-st',el))e.status=val(el,'pd-st');e.desc=val(el,'pd-desc');if($('#pd-plan',el))e.plan=val(el,'pd-plan');e.lead=val(el,'pd-lead')||e.lead;
        $$('[data-wn]',el).forEach(x=>e.works[+x.dataset.wn].n=x.value);$$('[data-we]',el).forEach(x=>e.works[+x.dataset.we].exec=x.value);$$('[data-wd]',el).forEach(x=>e.works[+x.dataset.wd].due=x.value||null)};
      $('#pd-resp',el).onclick=ev=>{const b=ev.target.closest('[data-e]');if(!b)return;snap();const id=b.dataset.e;e.resps=e.resps.includes(id)?e.resps.filter(x=>x!==id):[...e.resps,id];if(!e.resps.includes(e.lead))e.lead=e.resps[0]||'';m.draw()};
      $('#pd-wadd',el).onclick=()=>{snap();e.works.push({n:'',exec:e.lead||S.me,due:e.to,done:false});m.draw();const l=$$('[data-wn]',el);l.length&&l[l.length-1].focus()};
      $$('[data-wrm]',el).forEach(b=>b.onclick=()=>{snap();e.works.splice(+b.dataset.wrm,1);m.draw()});
      $('#pd-ok',el).onclick=()=>{snap();const cp=p0?p0.cp:c0?c0.id:e.cp;const plan=e.plan===''||e.plan==null?null:parseNum(e.plan);const paid=p0?projPaid(p0):0;
        const ok=[setErr(el,'pd-name',e.name?'':'Введите название'),p0||c0?true:setErr(el,'pd-cp',cp?'':'Выберите контрагента'),setErr(el,'pd-to',!e.from||!e.to?'Укажите даты':e.to<e.from?'Окончание раньше начала':''),setErr(el,'pd-resp',e.resps.length?'':'Выберите хотя бы одного ответственного'),
          mv?setErr(el,'pd-plan',plan!=null&&(isNaN(plan)||plan<0)?'Введите сумму или оставьте пустым':plan!=null&&plan<paid?`Не меньше уже полученного: ${som(paid)}`:''):true].every(Boolean);if(!ok)return;
        const works=e.works.filter(w=>w.n.trim()).map(w=>({n:w.n.trim(),exec:w.exec,due:w.due,done:!!w.done}));
        const o={name:e.name,from:e.from,to:e.to,status:e.status,resps:e.resps,lead:e.lead||e.resps[0],desc:e.desc,works};if(mv)o.plan=plan;
        if(p0){Object.assign(p0,o);log('p',p0.id,'Проект изменён',p0.cp);m.close();refreshAll();toast('Проект сохранён','briefcase');return}
        const p=born(Object.assign({id:'p'+(PROJECTS.length+1)+'n',cp,plan:null,pays:[],files:[]},o));PROJECTS.push(p);log('p',p.id,`Проект «${p.name}» создан`,cp);m.close();refreshAll();toast('Проект создан','briefcase');openProject(p)}}})});
}

